const { greet, add, multiply } = require('./utils');

function main() {
  const name = process.argv[2] || 'World';
  console.log(greet(name));

  if (process.argv.includes('--demo')) {
    console.log(`2 + 3 = ${add(2, 3)}`);
    console.log(`4 * 5 = ${multiply(4, 5)}`);
  }
}

main();

module.exports = { main };

/**
 * Greets a person by name.
 * @param {string} name - The name to greet.
 * @returns {string} The greeting message.
 */
function greet(name) {
  if (!name || typeof name !== 'string') {
    return 'Hello, World!';
  }
  return `Hello, ${name}!`;
}

/**
 * Adds two numbers.
 * @param {number} a - First number.
 * @param {number} b - Second number.
 * @returns {number} The sum.
 */
function add(a, b) {
  return a + b;
}

/**
 * Multiplies two numbers.
 * @param {number} a - First number.
 * @param {number} b - Second number.
 * @returns {number} The product.
 */
function multiply(a, b) {
  return a * b;
}

module.exports = { greet, add, multiply };

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { greet, add, multiply } = require('../src/utils');

describe('greet', () => {
  it('should greet with given name', () => {
    assert.equal(greet('Alice'), 'Hello, Alice!');
  });

  it('should return default greeting for empty input', () => {
    assert.equal(greet(), 'Hello, World!');
  });

  it('should return default greeting for non-string input', () => {
    assert.equal(greet(null), 'Hello, World!');
    assert.equal(greet(42), 'Hello, World!');
  });
});

describe('add', () => {
  it('should add two positive numbers', () => {
    assert.equal(add(2, 3), 5);
  });

  it('should handle negative numbers', () => {
    assert.equal(add(-1, 1), 0);
  });

  it('should handle zero', () => {
    assert.equal(add(0, 5), 5);
  });
});

describe('multiply', () => {
  it('should multiply two numbers', () => {
    assert.equal(multiply(4, 5), 20);
  });

  it('should multiply by zero', () => {
    assert.equal(multiply(5, 0), 0);
  });

  it('should handle negative numbers', () => {
    assert.equal(multiply(-3, 4), -12);
  });
});

